INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q6891', 'Battle of Bagradas', 'The Battle of the Bagradas River (the ancient name of the Medjerda), also known as the Battle of Tunis, was a victory by a Carthaginian army led by Xanthippus over a Roman army led by Marcus Atilius Regulus in the spring of 255 BC, nine years into the First Punic War. The previous year, the newly constructed Roman navy established naval superiority over Carthage.', -255, NULL, NULL, NULL, NULL, NULL, 'year', '255 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_the_Bagradas_River_(255_BC)'),
  ('Q815118', 'Siege of Aspis', 'The siege of Aspis or Clupea was fought in 256 BC between Carthage and the Roman Republic. It was the first fighting on African land during the First Punic War.', -255, NULL, NULL, NULL, NULL, NULL, 'year', '255 BCE', 45, 'https://en.wikipedia.org/wiki/Siege_of_Aspis'),
  ('Q963839', 'Battle of Adys', 'The battle of Adys (or Adis) took place in late 256 BC during the First Punic War between a Carthaginian army jointly commanded by Bostar, Hamilcar and Hasdrubal and a Roman army led by Marcus Atilius Regulus. Earlier in the year, the new Roman navy had established naval superiority and used this advantage to invade the Carthaginian homeland, which roughly aligned with modern Tunisia in North Africa.', -255, NULL, NULL, NULL, NULL, NULL, 'year', '255 BCE', 57, 'https://en.wikipedia.org/wiki/Battle_of_Adys'),
  ('Q928903', 'Battle of Utica', 'The Battle of Utica took place early in 240 BC between a Carthaginian army commanded by Hanno and a force of rebellious mutineers possibly led by Spendius. It was the first major engagement of the Mercenary War between Carthage and the combined forces of mutinous ex-Carthaginian troops and rebellious African cities which broke out in the wake of the First Punic War.', -240, NULL, NULL, NULL, NULL, NULL, 'year', '240 BCE', 47, 'https://en.wikipedia.org/wiki/Battle_of_Utica'),
  ('Q1132393', 'Mercenary War', 'The Mercenary War, also known as the Truceless War, was a mutiny by troops that were employed by Carthage at the end of the First Punic War (264–241 BC), supported by uprisings of African settlements revolting against Carthaginian control. It lasted from 241 to late 238 or early 237 BC and ended with Carthage suppressing both the mutiny and the revolt.', -240, NULL, NULL, -238, NULL, NULL, 'year', '240 BCE – 238 BCE', 69, 'https://en.wikipedia.org/wiki/Mercenary_War'),
  ('Q2888088', 'Battle of the Bagradas River', 'The Battle of the Bagradas River was fought between a Carthaginian army led by Hamilcar Barca, who was victorious, and a rebel force led by Spendius. The battle in 240 BC was fought in what is now northeast Tunisia.', -240, NULL, NULL, NULL, NULL, NULL, 'year', '240 BCE', 47, 'https://en.wikipedia.org/wiki/Battle_of_the_Bagradas_River_(240_BC)'),
  ('Q3070000', 'Siege of Tunis', 'During the siege of Tunis in October 238 BC a rebel army under Mathos was besieged by a Carthaginian force under Hamilcar Barca and Hannibal. A portion of the Carthaginian army, which had served in Sicily during the First Punic War, mutinied in late 241 BC in the wake of Carthage''s defeat, starting the Mercenary War.', -238, 10, NULL, NULL, NULL, NULL, 'month', 'October 238 BCE', 43, 'https://en.wikipedia.org/wiki/Siege_of_Tunis_(Mercenary_War)'),
  ('Q1353773', 'Battle of the Great Plains', 'The battle of the Great Plains was fought in 203 BC in modern Tunisia between a Roman army commanded by Publius Cornelius Scipio, and allied Carthaginian and Numidian armies commanded by Hasdrubal Gisco and Syphax respectively. The battle was part of the Second Punic War and resulted in a heavy defeat for Carthage.', -203, NULL, NULL, NULL, NULL, NULL, 'year', '203 BCE', 53, 'https://en.wikipedia.org/wiki/Battle_of_the_Great_Plains'),
  ('Q2888065', 'Battle of Utica', 'The battle of Utica was fought in 203 BC between a Roman army commanded by Publius Cornelius Scipio and the allied armies of Carthage and Numidia, commanded by Hasdrubal Gisgo and Syphax respectively. The battle was part of the Second Punic War and resulted in a heavy defeat for Carthage.', -203, NULL, NULL, NULL, NULL, NULL, 'year', '203 BCE', 51, 'https://en.wikipedia.org/wiki/Battle_of_Utica_(203_BC)'),
  ('Q200056', 'Battle of Zama', 'The Battle of Zama was fought in 202 BC in what is now Tunisia between a Roman army commanded by Scipio Africanus and a Carthaginian army commanded by Hannibal. The battle was part of the Second Punic War and resulted in such a severe defeat for the Carthaginians that they capitulated, while Hannibal was forced into exile.', -202, 10, 19, NULL, NULL, NULL, 'day', '19 October 202 BCE', 77, 'https://en.wikipedia.org/wiki/Battle_of_Zama'),
  ('Q9377248', 'Battle of Oroscopa', 'The Battle of Oroscopa was fought between a Carthaginian army of more than 30,000 men commanded by the general Hasdrubal and a Numidian force of unknown size under its king, Masinissa. It took place in late 151 BC near the ancient town of Oroscopa in what is now north western Tunisia.', -151, NULL, NULL, NULL, NULL, NULL, 'year', '151 BCE', 39, 'https://en.wikipedia.org/wiki/Battle_of_Oroscopa'),
  ('Q6334', 'Third Punic War', 'The Third Punic War (149–146 BC) was the third and last of the Punic Wars fought between Carthage and Rome. The war was fought entirely within Carthaginian territory, in what is now northern Tunisia.', -149, NULL, NULL, -146, NULL, NULL, 'year', '149 BCE – 146 BCE', 78, 'https://en.wikipedia.org/wiki/Third_Punic_War'),
  ('Q815160', 'Siege of Carthage', 'The siege of Carthage was the main engagement of the Third Punic War fought between Carthage and Rome. It consisted of the nearly three-year siege of the Carthaginian capital, Carthage (a little northeast of Tunis).', -149, NULL, NULL, -146, NULL, NULL, 'year', '149 BCE – 146 BCE', 63, 'https://en.wikipedia.org/wiki/Siege_of_Carthage_(Third_Punic_War)'),
  ('Q7443103', 'Second Battle of Nepheris', 'The Battle of Nepheris was the second battle of the Third Punic War that took place at Nepheris in late 147 BC. The battle was fought between the forces of the Roman Republic, commanded by Scipio Aemilianus, and the forces of Carthage who were commanded by Diogenes of Carthage. After the Roman defeat at the Battle of the Port of Carthage, Scipio Aemilianus decided to destroy the Carthaginian army at Nepheris, a stronghold south of the capital where the previous year the Romans had suffered a defeat at the First Battle of Nepheris against Hasdrubal the Boetharch.', -147, NULL, NULL, NULL, NULL, NULL, 'year', '147 BCE', 34, 'https://en.wikipedia.org/wiki/Battle_of_Nepheris_(147_BC)'),
  ('Q3822875', 'Siege of Thala', 'The siege of Thala, part of the Jugurthine War, was an invasion of the Numidian town of Thala by a Roman army. The Romans were commanded by the proconsul Quintus Caecilius Metellus, the Thalans by an unknown Numidian commander.', -108, NULL, NULL, NULL, NULL, NULL, 'year', '108 BCE', 37, 'https://en.wikipedia.org/wiki/Siege_of_Thala'),
  ('Q2416094', 'Battle of Utica', 'The Battle of Utica (49 BC) in Caesar''s Civil War was fought between Julius Caesar''s general Gaius Scribonius Curio and Pompeian legionaries commanded by Publius Attius Varus supported by Numidian cavalry and foot soldiers sent by King Juba I of Numidia. Curio defeated the Pompeians and Numidians and drove Varus back into the town of Utica.', -49, NULL, NULL, NULL, NULL, NULL, 'year', '49 BCE', 45, 'https://en.wikipedia.org/wiki/Battle_of_Utica_(49_BC)'),
  ('Q762458', 'Battle of Ruspina', 'The Battle of Ruspina was fought on 4 January 46 BC in the Roman province of Africa, between the Republican forces of the Optimates and forces loyal to Julius Caesar. The Republican army was commanded by Titus Labienus, Caesar''s former lieutenant during the Gallic Wars who had defected to the Republican side at the beginning of the civil war.', -46, 1, 4, NULL, NULL, NULL, 'day', '4 January 46 BCE', 55, 'https://en.wikipedia.org/wiki/Battle_of_Ruspina'),
  ('Q849653', 'Battle of Thapsus', 'The Battle of Thapsus was a military engagement that took place on April 6, 46 BC near Thapsus (in modern Tunisia). The forces of the Optimates, led by Quintus Caecilius Metellus Scipio, were defeated by the forces of Julius Caesar.', -46, 4, 6, NULL, NULL, NULL, 'day', '6 April 46 BCE', 65, 'https://en.wikipedia.org/wiki/Battle_of_Thapsus'),
  ('Q30742713', 'Capture of Carthage', 'The Battle of Carthage of 439 was when the city of Carthage was captured by the Vandals from the Western Roman Empire on 19 October 439. Under their leader Genseric, the Vandals crossed the Strait of Gibraltar into Africa and captured Hippo Regius in August 431, which they made the capital of their kingdom.', 439, 10, 19, NULL, NULL, NULL, 'day', '19 October 439', 43, 'https://en.wikipedia.org/wiki/Capture_of_Carthage_(439)'),
  ('Q598261', 'Battle of Tricamarum', 'The Battle of Tricamarum took place on 15 December 533 between the armies of the Byzantine Empire, under Belisarius, and the Vandal Kingdom, commanded by King Gelimer and his brother Tzazo. Following the Byzantine victory at the Battle of Ad Decimum in September 533, Belisarius captured Carthage and prepared to face the remaining Vandal forces led by King Gelimer.', 533, 12, 15, NULL, NULL, NULL, 'day', '15 December 533', 60, 'https://en.wikipedia.org/wiki/Battle_of_Tricamarum'),
  ('Q1127353', 'Battle of Ad Decimum', 'The Battle of Ad Decimum took place on 13 September 533 between the armies of the Vandals, commanded by King Gelimer, and the Byzantine Empire, under the command of General Belisarius. The Vandal Kingdom under King Hilderic maintained close ties with Emperor Justinian I, but Hilderic''s acceptance of Chalcedonian Christianity over Arianism led to his overthrow by his cousin Gelimer in 531.', 533, 9, 13, NULL, NULL, NULL, 'day', '13 September 533', 63, 'https://en.wikipedia.org/wiki/Battle_of_Ad_Decimum'),
  ('Q12244179', 'Battle of Sufetula', 'The Battle of Sufetula (Arabic: معركة سبيطلة, romanized: Ma''rakat Sbeitla) took place in 647 between the Arab Muslim forces of the Rashidun Caliphate and the Byzantine Exarchate of Africa.', 647, NULL, NULL, NULL, NULL, NULL, 'year', '647', 48, 'https://en.wikipedia.org/wiki/Battle_of_Sufetula_(647)'),
  ('Q22690035', 'Battle of al-Qarn', 'The Battle of Al-Qarn was a military engagement between the Umayyad governor of ifriqya Handhala ibn Safwan al-Kalbi and the Sufrite Berber Kharijites led by Ukasha ibn Ayub al-Fezari, the Umayyads were victorious and Ukasha would later get captured and executed.', 742, 5, NULL, NULL, NULL, NULL, 'month', 'May 742', 34, 'https://en.wikipedia.org/wiki/Battle_of_al-Qarn'),
  ('Q243684', 'Eighth Crusade', 'The Eighth Crusade was the second Crusade launched by Louis IX of France, this one against the Hafsid dynasty in Ifriqiya in 1270. It is also known as the Crusade of Louis IX Against Tunis or the Second Crusade of Louis.', 1270, NULL, NULL, 1270, 10, 30, 'year', '1270', 76, 'https://en.wikipedia.org/wiki/Eighth_Crusade'),
  ('Q700893', 'Conquest of Tunis', 'The Conquest of Tunis (called Jornada de Túnez in Spanish sources) in 1535 occurred when the Holy Roman Emperor Charles V and his allies captured the city of Tunis from the control of the Ottoman Empire. The Catholic fleet, which included admirals Andrea Doria and Bazán the Elder, captured the fleet of grand Ottoman admiral Hayreddin Barbarossa, who had turned Tunis into his naval base for future invasions of Italy and Spain.', 1535, 6, 16, 1535, 7, 21, 'day', '16 June 1535 – 21 July 1535', 61, 'https://en.wikipedia.org/wiki/Conquest_of_Tunis_(1535)'),
  ('Q5037032', 'Capture of Mahdia', 'The capture of Mahdia was an amphibious military operation that took place from June to September, 1550, during the struggle between the Ottoman Empire and the Spanish Habsburgs for the control of the Mediterranean. A Spanish naval expedition under the command of the Genoese condottiero and admiral Andrea Doria and the Spaniard Bernardino de Mendoza, supported by the Knights of Malta under their Grand Master Claude de la Sengle, besieged and captured the Ottoman stronghold of Mahdia or Mahdiye, defended by the Ottoman Admiral Turgut Reis, known as Dragut, who was using the place as a base…', 1550, 6, 28, 1550, 9, 8, 'day', '28 June 1550 – 8 September 1550', 37, 'https://en.wikipedia.org/wiki/Capture_of_Mahdia_(1550)'),
  ('Q2664371', 'Conquest of Tunis', 'The conquest of Tunis in 1574 marked the conquest of Tunis by the Ottoman Empire over the Spanish Empire, which had seized the place a year earlier. The event virtually determined the supremacy in North Africa vied between both empires in favour of the former, sealing the Ottoman domination over eastern and central Maghreb, with the Ottoman dependencies in Algiers, Tunis and Tripoli ensuing coming to experience a golden age as corsair states.', 1574, 7, 12, 1574, 9, 13, 'day', '12 July 1574 – 13 September 1574', 57, 'https://en.wikipedia.org/wiki/Conquest_of_Tunis_(1574)'),
  ('Q86670059', 'Tunisian-Algerian War of 1735', 'The Capture of Tunis occurred in 1735 when the Dey of Algiers sent an invasion force to Tunis in order to install Ali Pasha as the Bey. After a failed revolt Ali Pasha took refuge in Algiers where he managed to gain the support of the Dey.', 1735, 9, 4, 1735, 9, 7, 'day', '4 September 1735 – 7 September 1735', 26, 'https://en.wikipedia.org/wiki/Capture_of_Tunis_(1735)'),
  ('Q12203924', 'Mejba Revolt', 'The Mejba Revolt (1864–65) was a rebellion in Tunisia against the doubling of an unpopular poll tax (the mejba) imposed on his subjects by Sadok Bey. The most extensive revolt against the rule of the Husainid Beys of Tunis, it saw uprisings all over the country and came close to prompting military intervention by Britain and France.', 1864, NULL, NULL, 1865, NULL, NULL, 'year', '1864–1865', 34, 'https://en.wikipedia.org/wiki/Mejba_Revolt'),
  ('Q808027', 'Treaty of Bardo', 'The Treaty of Bardo (French: Traité du Bardo, Arabic: معاهدة باردو) or Treaty of Ksar Saïd established a French protectorate over Tunisia that lasted until World War II. It was signed on 12 May 1881 between representatives of France and the Tunisian bey Muhammed as-Sadiq, placing Tunisia under the control of the French Resident-General. The treaty allowed France to control certain geographical areas under the guise of re-establishing order and protecting the Bey from internal opposition and also gave France responsibility for foreign-policy decisions of Tunisia.', 1881, 5, 12, 1956, 3, 20, 'day', '12 May 1881 – 20 March 1956', 55, 'https://en.wikipedia.org/wiki/Treaty_of_Bardo'),
  ('Q2996359', 'Conventions of La Marsa', 'The Conventions of La Marsa (Arabic: اتفاقية المرسى) supplementing the Treaty of Bardo were signed by the Bey of Tunis Ali III ibn al-Husayn and the French Resident General Paul Cambon in the Dar al-Taj Palace on 8 June 1883. They provided for France to repay Tunisia''s international debt so it could abolish the International Debt Commission and thereby remove any obstacles to a French protectorate in Tunisia.', 1883, 6, 8, NULL, NULL, NULL, 'day', '8 June 1883', 41, 'https://en.wikipedia.org/wiki/Conventions_of_La_Marsa'),
  ('Q852365', 'Tunisia campaign', 'The Tunisian campaign (also known as the Battle of Tunisia) was a series of battles that took place in Tunisia during the North African campaign of the Second World War, between Axis and Allied forces from 17 November 1942 to 13 May 1943. The Allies consisted of British Imperial Forces, including a Greek contingent, with American and French corps.', 1942, 11, 17, 1943, 5, 9, 'day', '17 November 1942 – 9 May 1943', 68, 'https://en.wikipedia.org/wiki/Tunisian_campaign'),
  ('Q327099', 'Battle of Kasserine Passe', 'The Battle of Kasserine Pass was a series of engagements which took place from 19–24 February 1943 around Kasserine Pass, a 2-mile-wide (3.2 km) gap in the Grand Dorsal chain of the Atlas Mountains in west central Tunisia. It was a part of the Tunisian campaign of World War II. The Axis forces, led by Generalfeldmarschall Erwin Rommel, were primarily from the Afrika Korps Assault Group, the Italian Centauro Armored Division and two Panzer divisions detached from the 5th Panzer Army.', 1943, NULL, NULL, 1943, 2, 25, 'year', '1943', 68, 'https://en.wikipedia.org/wiki/Battle_of_Kasserine_Pass'),
  ('Q1154689', 'Battle of the Mareth Line', 'The Battle of the Mareth Line or the Battle of Mareth was an attack in the Second World War by the British Eighth Army (General Bernard Montgomery) in Tunisia, against the Mareth Line held by the Italo–German 1st Army (General Giovanni Messe). It was the first big operation by the Eighth Army since the Second Battle of El Alamein 4+1⁄2 months earlier.', 1943, 3, 16, 1943, 3, 31, 'day', '16 March 1943 – 31 March 1943', 52, 'https://en.wikipedia.org/wiki/Battle_of_the_Mareth_Line'),
  ('Q4871224', 'Battle of Hill 609', 'The Battle of Hill 609 took place at Djebel Tahent in northwestern Tunisia during the Tunisian campaign of World War II. The battle, part of Operation Vulcan, was for control over the key strategic height known as Hill 609 and its surrounding area between the American forces of the U.S. II Corps and German units of the Afrika Korps.', 1943, 4, 27, 1943, 5, 1, 'day', '27 April 1943 – 1 May 1943', 39, 'https://en.wikipedia.org/wiki/Battle_of_Hill_609'),
  ('Q16165490', 'Battle of Longstop Hill', 'The 2nd Battle of Longstop Hill or the Capture of Longstop Hill took place in Tunisia during the Tunisia Campaign of World War II from 21 to 26 April 1943. The battle, part of Operation Vulcan, was fought for control over the heights of Djebel el Ahmera and Djebel Rhar, together known as Longstop Hill and vicinity, between the British forces of the First Army and German units of the 5th Panzer Army.', 1943, 4, 22, 1943, 4, 23, 'day', '22 April 1943 – 23 April 1943', 37, 'https://en.wikipedia.org/wiki/Battle_of_Longstop_Hill'),
  ('Q7853205', 'Tunisian independence', 'Tunisian independence was a process that occurred from 1952 to 1956 between France and an independence movement, led by Habib Bourguiba. Bourguiba''s negotiations with France succeeded in ending the colonial protectorate and achieving independence.', 1952, NULL, NULL, 1956, 3, 20, 'year', '1952 – 20 March 1956', 26, 'https://en.wikipedia.org/wiki/Tunisian_independence'),
  ('Q879267', 'Bizerte crisis', 'The Bizerte crisis (French: Crise de Bizerte; Arabic: أحداث بنزرت, romanized: ʾAḥdāth Bīnzart) occurred in July 1961 when Tunisia imposed a blockade on the French naval base at Bizerte, Tunisia, hoping to force its evacuation. The crisis culminated in a three-day battle between French and Tunisian forces that left 630 Tunisians and 24 French dead.', 1961, 7, 19, 1961, 7, 23, 'day', '19 July 1961 – 23 July 1961', 58, 'https://en.wikipedia.org/wiki/Bizerte_crisis'),
  ('Q16987715', 'Italy–Tunisia Delimitation Agreement', 'The Italy–Tunisia Delimitation Agreement is a 1971 treaty between Italy and Tunisia in which the two countries agreed to delimit a maritime boundary between them in the continental shelf. The text of the treaty sets out a complex boundary in the Strait of Sicily representing an equidistant line between Sicily and Tunisia, with the exception of Pantelleria and the Pelagian Islands (Lampedusa, Linosa and Lampione).', 1971, NULL, NULL, NULL, NULL, NULL, 'year', '1971', 34, 'https://en.wikipedia.org/wiki/Italy%E2%80%93Tunisia_Delimitation_Agreement'),
  ('Q8676049', '1987 Tunisian coup d''état', 'The 1987 Tunisian coup d''état involved the bloodless ousting of the aging president of Tunisia Habib Bourguiba on 7 November 1987, and his replacement as president by his recently appointed prime minister, Zine El Abidine Ben Ali. The action was justified by reference to Bourguiba''s failing health and Article 57 of the country''s constitution.', 1987, 11, 7, NULL, NULL, NULL, 'day', '7 November 1987', 43, 'https://en.wikipedia.org/wiki/1987_Tunisian_coup_d''%C3%A9tat'),
  ('Q632787', 'Insurgency in the Maghreb', 'An Islamist insurgency is taking place in the Maghreb region of North Africa, followed on from the end of the Algerian Civil War in 2002. The Algerian militant group Salafist Group for Preaching and Combat (GSPC) allied itself with al-Qaeda to eventually become al-Qaeda in the Islamic Maghreb (AQIM).', 2002, 4, 11, NULL, NULL, NULL, 'day', '11 April 2002', 58, 'https://en.wikipedia.org/wiki/Insurgency_in_the_Maghreb_(2002%E2%80%93present)'),
  ('Q962475', 'Tuninter Flight 1153', 'Tuninter Flight 1153 was a scheduled international passenger flight flown by Tuninter Airlines from Bari International Airport in Italy, to Djerba-Zarzis Airport on the Tunisian island of Djerba. On 6 August 2005, the Tuninter ATR 72 ditched into the Mediterranean Sea about 18 miles (29 km) from the city of Palermo.', 2005, 8, 6, NULL, NULL, NULL, 'day', '6 August 2005', 61, 'https://en.wikipedia.org/wiki/Tuninter_Flight_1153'),
  ('Q46959', 'Tunisian revolution', 'The Tunisian revolution (Arabic: الثورة التونسية), also called the Jasmine Revolution and Tunisian Revolution of Dignity, was an intensive 28-day campaign of civil resistance. It included a series of street demonstrations which took place in Tunisia, and led to the ousting of longtime dictator Zine El Abidine Ben Ali in January 2011.', 2010, 12, 24, 2011, 1, 14, 'day', '24 December 2010 – 14 January 2011', 79, 'https://en.wikipedia.org/wiki/Tunisian_revolution'),
  ('Q3477179', 'Battle of Wazzin', 'The Battle of Wazzin refers to a series of engagements during the First Libyan Civil War fought between Anti-Gaddafi forces and the Libyan Arab Jamahiriya for control of the town of Wazzin near the western Libya-Tunisia border. The battle entered into Tunisian territory on several occasions, prompting clashes between the Tunisian Armed Forces and Gaddafi Loyalists.', 2011, 4, 21, 2011, 7, 29, 'day', '21 April 2011 – 29 July 2011', 37, 'https://en.wikipedia.org/wiki/Battle_of_Wazzin'),
  ('Q23198510', 'Islamic State insurgency in Tunisia', 'The Islamic State Insurgency in Tunisia refers to the low–level militant and terror activity of the Islamic State branch in Tunisia from 2015 to 2022. The activity of the Islamic State (IS) in Tunisia began in June 2015, with the Sousse attacks, though an earlier terror incident in Bardo Museum in March 2015 was claimed by IS, while the Tunisian government blamed Okba Ibn Nafaa Brigade for the attack.', 2012, NULL, NULL, NULL, NULL, NULL, 'year', '2012', 39, 'https://en.wikipedia.org/wiki/Islamic_State_insurgency_in_Tunisia'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods');
